  <div class="stick-wrap" id="lstick-wrap"><div class="stick-inner" id="lstick-inner">${Te}<div class="stick-img-clip">${Bt}</div>${Ve}${n.leftStickCometEnabled?'<div class="stick-comet-wrap"><canvas id="lstick-comet"></canvas></div>':""}${n.leftStickElectricEnabled?'<div class="stick-electric-wrap"><canvas id="lstick-electric"></canvas></div>':""}${n.leftStickSparkEnabled?'<div class="stick-spark-wrap"><canvas id="lstick-spark"></canvas></div>':""}<div class="stick-press-glow" id="lstick-press-glow"></div><div class="stick-press-dark" id="lstick-press-dark"></div></div></div>
