    var rx=dead(gp.axes[2]||0), ry=dead(gp.axes[3]||0);
    var lPressed = gp.buttons[L_PRESS_BTN] ? gp.buttons[L_PRESS_BTN].pressed : false;
    var rPressed = gp.buttons[R_PRESS_BTN] ? gp.buttons[R_PRESS_BTN].pressed : false;
